1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.Locale;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's {@code identityKey}: the single value that consolidates all
9	 * duplicate detection for {@code POST /api/owners}. The key is
10	 * {@code normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty)},
11	 * where the telephone is in E.164 form (see {@link E164Telephone}) and the email is
12	 * lower-cased. Two owners are duplicates only when their WHOLE keys are equal, so — because
13	 * the telephone is part of the key — two members of the same household (same
14	 * {@code householdId}) with different telephones have different keys and are both allowed.
15	 *
16	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
17	 * tripping the one-public-method-per-function rule.
18	 */
19	public final class OwnerIdentity {
20	
21	    private OwnerIdentity() {
22	    }
23	
24	    /** The identity key of a stored owner, using its E.164 telephone, email and household id. */
25	    public static String key(Owner owner) {
26	        return key(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
27	    }
28	
29	    /**
30	     * The identity key for the given parts. The telephone is normalized to E.164 (an
31	     * unparseable telephone contributes empty); the email is lower-cased; a null email or
32	     * household id contributes an empty segment.
33	     */
34	    public static String key(String telephone, String email, String householdId) {
35	        String tel = E164Telephone.normalizeOrNull(telephone);
36	        String normalizedTelephone = tel == null ? "" : tel;
37	        String normalizedEmail = email == null ? "" : email.toLowerCase(Locale.ROOT);
38	        String household = householdId == null ? "" : householdId;
39	        return normalizedTelephone + "|" + normalizedEmail + "|" + household;
40	    }
41	}
