1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Assigns the owner's {@code customerCode}, formatted {@code <CITY3>-<LAST3>-<NNNN>}
9	 * where CITY3 is the upper-cased first three letters of the city, LAST3 is the
10	 * upper-cased first three letters of the last name and NNNN is a per-city 4-digit
11	 * zero-padded sequence equal to one more than the number of owners already in that
12	 * city (e.g. {@code LON-SMI-0007}).
13	 *
14	 * <p>Runs after {@code BuildOwner} (so the owner exists) but before {@code SaveOwner}
15	 * (so the owner being created is not yet counted), mutating the owner in place.
16	 */
17	public class AssignCustomerCode {
18	
19	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
20	        String city = owner.getCity();
21	        long sequence = ownerRepository.findAll().stream()
22	                .filter(o -> city == null ? o.getCity() == null : city.equals(o.getCity()))
23	                .count() + 1;
24	        String city3 = prefix3(city);
25	        String last3 = prefix3(owner.getLastName());
26	        owner.setCustomerCode(String.format("%s-%s-%04d", city3, last3, sequence));
27	    }
28	
29	    private static String prefix3(String value) {
30	        String v = value == null ? "" : value;
31	        return v.substring(0, Math.min(3, v.length())).toUpperCase();
32	    }
33	}
