3	import org.slf4j.Logger;
4	import org.slf4j.LoggerFactory;
5	
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Emits an audit line on successful owner creation via the dedicated {@code AUDIT}
11	 * logger, carrying the owner id, the {@code customerCode} and the
12	 * {@code registrationDate}.
13	 *
14	 * <p>Runs after {@code SaveOwner} so the owner id has been assigned.
15	 */
16	public class AuditOwnerCreated {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    public void service(@Val Owner owner) {
21	        AUDIT.info("Owner created id={} customerCode={} registrationDate={}",
22	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
23	    }
24	}
