26	    @Mapping(target = "locality", expression = "java(toLocality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(toContactPreference(owner))")
28	    @Mapping(target = "identityKey", expression = "java(toIdentityKey(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's {@code identityKey}: the single value that consolidates all
33	     * duplicate detection, {@code normalizedTelephone + '|' + (email or empty) + '|' +
34	     * (householdId or empty)}.
35	     */
36	    default String toIdentityKey(Owner owner) {
37	        return org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.key(owner);
38	    }
39	
40	    /**
41	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
42	     * otherwise {@code PHONE}.
43	     */
44	    default String toContactPreference(Owner owner) {
45	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
46	        return hasEmail ? "EMAIL" : "PHONE";
47	    }
48	
49	    /**
50	     * Fixed city-to-region table used to derive the owner's locality.
51	     */
52	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
53	            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
54	
55	    /**
56	     * Region -> inclusive 4-digit postcode range {low, high} used to derive the owner's
57	     * locality from the postcode.
58	     */
59	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
60	            "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
61	
62	    /**
63	     * Derives the owner's locality (region), preferring the postcode: look up the region by
64	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only fall back
65	     * to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the
66	     * postcode is absent or in no known range. Returns {@code UNKNOWN} when neither yields a
67	     * region.
68	     */
69	    default String toLocality(Owner owner) {
70	        String postcode = owner.getPostcode();
71	        if (postcode != null) {
72	            try {
73	                int value = Integer.parseInt(postcode.trim());
74	                for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
75	                    int[] range = entry.getValue();
76	                    if (value >= range[0] && value <= range[1]) {
77	                        return entry.getKey();
78	                    }
79	                }
80	            } catch (NumberFormatException ex) {
81	                // not a numeric postcode; fall back to the city table
82	            }
83	        }
84	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
85	    }
86	
87	    /**
88	     * Derives the owner's numeric membership level (1 to 3), computed on creation: start at 1;
89	     * add 1 when an email is present; add 1 when the owner has no namesakes ({@code namesakeCount}
90	     * is 0); capped at 3 (level 4 is reserved for tenure).
91	     */
92	    default Integer toMembershipLevel(Owner owner) {
93	        int level = 1;
94	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
95	        if (hasEmail) {
96	            level++;
97	        }
98	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
99	        if (unique) {
100	            level++;
101	        }
102	        return Math.min(level, 3);
103	    }
104	
105	    /**
106	     * Derives the owner's membership number as {@code <customerCode>-M<YY>}, where YY is the
107	     * last two digits of the registration-date year (e.g. {@code SMI-0007-M26}). Returns null
108	     * when either the customer code or registration date is absent (e.g. unmigrated seed data).
109	     */
110	    default String toMembershipNumber(Owner owner) {
111	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
112	            return null;
113	        }
114	        return owner.getCustomerCode() + "-M" + String.format("%02d", owner.getRegistrationDate().getYear() % 100);
115	    }
116	
117	    /**
118	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the
119	     * digits contained in the {@code customerCode}. Returns null when the customer code is
120	     * absent (e.g. unmigrated seed data).
121	     */
122	    default Integer toCheckDigit(Owner owner) {
123	        String customerCode = owner.getCustomerCode();
124	        if (customerCode == null) {
125	            return null;
126	        }
127	        int sum = 0;
128	        boolean dbl = true;
129	        for (int i = customerCode.length() - 1; i >= 0; i--) {
130	            char c = customerCode.charAt(i);
131	            if (c < '0' || c > '9') {
132	                continue;
133	            }
134	            int d = c - '0';
135	            if (dbl) {
136	                d *= 2;
137	                if (d > 9) {
138	                    d -= 9;
139	                }
140	            }
141	            sum += d;
142	            dbl = !dbl;
143	        }
144	        return (10 - (sum % 10)) % 10;
145	    }
146	
147	    Owner toOwner(OwnerDto ownerDto);
148	
149	    @Mapping(target = "id", ignore = true)
150	    @Mapping(target = "pets", ignore = true)
151	    @Mapping(target = "customerCode", ignore = true)
152	    @Mapping(target = "householdId", ignore = true)
153	    @Mapping(target = "namesakeCount", ignore = true)
154	    @Mapping(target = "householdSize", ignore = true)
155	    Owner toOwner(OwnerFieldsDto ownerDto);
156	
157	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
158	
159	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
160	
161	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
162	        OwnerPageDto ownerPageDto = new OwnerPageDto();
163	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
164	        ownerPageDto.setPage(ownerPage.getNumber());
165	        ownerPageDto.setSize(ownerPage.getSize());
166	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
167	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
168	        return ownerPageDto;
169	    }
170	}
