5	/**
6	 * Normalizes a postal address to a single canonical form: trimmed with runs of whitespace
7	 * collapsed to a single space, upper-cased, and common street-type abbreviations expanded
8	 * to their full word (ST -> STREET, RD -> ROAD, AVE -> AVENUE). Expansion matches whole
9	 * space-separated tokens only, so "12 MAIN ST" becomes "12 MAIN STREET" while a token such
10	 * as "TEST" is left untouched.
11	 *
12	 * <p>Every create-owner comparison of addresses (household duplicate detection and the
13	 * shared household id) runs through this so that inputs like "12 main st" and
14	 * "12 MAIN STREET" are treated as the same address.
15	 *
16	 * <p>A plain utility (not an OfficeFloor function), so it may expose helpers without
17	 * tripping the one-public-method-per-function rule.
18	 */
19	public final class AddressNormalizer {
20	
21	    private AddressNormalizer() {
22	    }
23	
24	    /**
25	     * @return the canonical address form; {@code ""} when the input is {@code null} or blank.
26	     */
27	    public static String normalize(String raw) {
28	        if (raw == null) {
29	            return "";
30	        }
31	        String collapsed = raw.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
32	        if (collapsed.isEmpty()) {
33	            return "";
34	        }
35	        String[] tokens = collapsed.split(" ");
36	        for (int i = 0; i < tokens.length; i++) {
37	            tokens[i] = expand(tokens[i]);
38	        }
39	        return String.join(" ", tokens);
40	    }
41	
42	    private static String expand(String token) {
43	        switch (token) {
44	            case "ST":
45	                return "STREET";
46	            case "RD":
47	                return "ROAD";
48	            case "AVE":
49	                return "AVENUE";
50	            default:
51	                return token;
52	        }
53	    }
54	}
